const EntranceLoader: React.FC<{ onFinished: () => void }> = ({ onFinished }) => {
  const [isFadingOut, setIsFadingOut] = React.useState(false);

  React.useEffect(() => {
    const fadeTimer = setTimeout(() => {
      setIsFadingOut(true);
    }, 2000); // Logo visible for 2 seconds

    const finishTimer = setTimeout(() => {
      onFinished();
    }, 2800); // Fade out duration is 800ms

    return () => {
      clearTimeout(fadeTimer);
      clearTimeout(finishTimer);
    };
  }, [onFinished]);

  return (
    <div className={`fixed inset-0 z-[100] flex items-center justify-center bg-[#0B1E39] transition-opacity duration-800 ease-in-out ${isFadingOut ? 'opacity-0' : 'opacity-100'}`}>
