const IndustryDetailPage: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const [industry, setIndustry] = React.useState<Industry | null>(null);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);
    const [isLightboxOpen, setIsLightboxOpen] = React.useState(false);
    const [currentImageIndex, setCurrentImageIndex] = React.useState(0);
    const { t } = useLanguage();

    React.useEffect(() => {
        if (id) {
            const fetchIndustry = async () => {
                try {
                    setLoading(true);
                    const data = await getIndustryById(id);
                    setIndustry(data);
                } catch (err) {
                    setError('Failed to load industry data.');
                } finally {
                    setLoading(false);
                }
            };
            fetchIndustry();
        }
    }, [id]);

    const openLightbox = (index: number) => {
        setCurrentImageIndex(index);
        setIsLightboxOpen(true);
    };

    const closeLightbox = () => setIsLightboxOpen(false);

    const goToNext = React.useCallback(() => {
        if (!industry) return;
        setCurrentImageIndex((prevIndex) => (prevIndex + 1) % industry.gallery.length);
    }, [industry]);

    const goToPrev = React.useCallback(() => {
        if (!industry) return;
        setCurrentImageIndex((prevIndex) => (prevIndex - 1 + industry.gallery.length) % industry.gallery.length);
    }, [industry]);

    React.useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (!isLightboxOpen) return;
            if (e.key === 'Escape') closeLightbox();
            if (e.key === 'ArrowRight') goToNext();
            if (e.key === 'ArrowLeft') goToPrev();
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isLightboxOpen, goToNext, goToPrev]);

    if (loading) {
        return <div className="flex justify-center items-center h-screen"><Loader /></div>;
    }

    if (error || !industry) {
        return (
            <div className="container mx-auto px-6 py-20 text-center">
                <h1 className="text-4xl font-bold text-white font-montserrat">{t('industryDetailPage.errorTitle', 'Industry Not Found')}</h1>
