const ProgressBar: React.FC<{ label: string; percentage: number; delay?: number }> = ({ label, percentage, delay = 0 }) => {
    const [ref, isInView] = useInView({ threshold: 0.5 });
    const [width, setWidth] = React.useState(0);

    React.useEffect(() => {
        if (isInView) {
            setTimeout(() => setWidth(percentage), delay);
        }
    }, [isInView, percentage, delay]);

    return (
        <div ref={ref as React.RefObject<HTMLDivElement>}>
            <div className="flex justify-between mb-1">
                <span className="text-base font-medium text-[#effefb] font-lato">{label}</span>
                <span className="text-sm font-medium text-white font-roboto-condensed">{width}%</span>
            </div>
            <div className="w-full bg-[#1E2B2B] rounded-full h-2.5">
                <div className="bg-gradient-to-r from-[#41737c] to-[#2D4F54] h-2.5 rounded-full progress-bar-fg" style={{ width: `${width}%` }}></div>
            </div>
        </div>
    );
};

const RadialProgress: React.FC<{ label: string; percentage: number }> = ({ label, percentage }) => {
    const [ref, isInView] = useInView({ threshold: 0.5 });
    const [progress, setProgress] = React.useState(0);

    React.useEffect(() => {
        if (isInView) {
            setProgress(percentage);
        }
    }, [isInView, percentage]);

    const radius = 50;
    const circumference = 2 * Math.PI * radius;
    const offset = circumference - (progress / 100) * circumference;

    return (
        <div ref={ref as React.RefObject<HTMLDivElement>} className="flex flex-col items-center">
            <svg className="w-40 h-40 transform -rotate-90" viewBox="0 0 120 120">
                <circle className="text-[#1E2B2B]" strokeWidth="8" stroke="currentColor" fill="transparent" r={radius} cx="60" cy="60" />
                <circle
                    className="text-[#41737c] radial-chart-fg"
                    strokeWidth="8"
                    strokeDasharray={circumference}
                    strokeDashoffset={offset}
                    strokeLinecap="round"
                    stroke="currentColor"
                    fill="transparent"
                    r={radius}
                    cx="60"
                    cy="60"
                />
            </svg>
            <span className="absolute text-3xl font-bold text-white mt-[52px] font-montserrat">{progress}%</span>
            <p className="mt-2 text-[#effefb] font-roboto-condensed text-lg">{label}</p>
        </div>
    );
};


