// --- 2. SEEDING LOGIC ---

const importData = async () => {
    try {
        await connectDB();

        console.log('--- DB Connected. Starting Seeding Process ---');

        // Step 1: Clear existing data
        await Promise.all([
            User.deleteMany(),
            Role.deleteMany(),
            Industry.deleteMany(),
            News.deleteMany(),
            Vacancy.deleteMany(),
            Applicant.deleteMany(),
            Media.deleteMany(),
            Page.deleteMany(),
            Inquiry.deleteMany(),
            SecurityLog.deleteMany(),
            Tender.deleteMany()
        ]);
        console.log('1. Cleared existing database collections.');

        // Step 2: Insert Roles
        const createdRoles = await Role.insertMany(rolesData);
        console.log('2. Roles Imported.');

        // Helper map: Role Name -> Role ID
        const roleMap = {};
        createdRoles.forEach(r => roleMap[r.name] = r._id);

        // Step 3: Insert Users (with mapped Roles)
        // We use User.create instead of insertMany to ensure the pre('save') hook runs for password hashing
        const usersToCreate = usersData.map(u => ({
            ...u,
            role: roleMap[u.roleName],
            password: 'password123' 
        }));

        const createdUsers = [];
        for (const u of usersToCreate) {
            createdUsers.push(await User.create(u));
        }
        console.log('3. Users Imported.');

        // Helper map: User Email -> User ID
        const userMap = {};
        const adminUser = createdUsers.find(u => u.email === 'admin@deig.gov.et');
        createdUsers.forEach(u => userMap[u.email] = u._id);

        // Step 4: Insert Industries
        await Industry.insertMany(industriesData);
        console.log('4. Industries Imported.');

        // Step 5: Insert Pages (Linked to Admin)
        const pagesWithUser = pagesData.map(p => ({ ...p, editedBy: adminUser._id }));
        await Page.insertMany(pagesWithUser);
        console.log('5. Pages Imported.');

        // Step 6: Insert News (Linked to Admin)
        const newsWithUser = newsData.map(n => ({ ...n, author: adminUser._id }));
        await News.insertMany(newsWithUser);
        console.log('6. News Imported.');

        // Step 7: Insert Vacancies & Applicants
        // Use a loop to create vacancies individually so we can map their new IDs to applicants
        const vacancyIdMap = {}; // Maps frontend 've-001' ID to MongoDB ObjectId

        for (const v of vacanciesData) {
            const newV = await Vacancy.create(v);
            // We store the frontend ID in the map for lookup
            vacancyIdMap[v.id] = newV._id; 
        }
        console.log('7. Vacancies Imported.');

        // Filter applicants to only those with valid vacancies and map the IDs
        const applicantsWithRef = applicantsData
            .filter(a => vacancyIdMap[a.vacancyId])
            .map(a => ({
                ...a,
                vacancy: vacancyIdMap[a.vacancyId]
            }));

        await Applicant.insertMany(applicantsWithRef);
        console.log('8. Applicants Imported & Linked.');

        // Step 8: Insert Media (Linked to Admin)
        const mediaWithUser = mediaData.map(m => ({ ...m, uploadedBy: adminUser._id }));
        await Media.insertMany(mediaWithUser);
        console.log('9. Media Imported.');

        // Step 9: Insert Tenders
        await Tender.insertMany(tendersData);
        console.log('10. Tenders Imported.');

        // Step 10: Insert Inquiries (Assign some to users)
        const inquiriesWithUser = inquiriesData.map(i => {
            // Assign 'Career' questions to HR, others to Admin
            const assignedUser = i.subject.includes('Career') ? 
                createdUsers.find(u => u.email === 'hr@deig.gov.et') : 
                adminUser;
            return { ...i, assignedTo: assignedUser ? assignedUser._id : adminUser._id };
        });
        await Inquiry.insertMany(inquiriesWithUser);
        console.log('11. Inquiries Imported.');

        // Step 11: Insert Security Logs (Linked to Admin)
        const logsWithUser = logsData.map(l => ({ ...l, user: adminUser._id }));
        await SecurityLog.insertMany(logsWithUser);
        console.log('12. Security Logs Imported.');

        console.log('--- Data Seeding Complete! ---');
        console.log('Default Admin Login: admin@deig.gov.et / password123');
        process.exit();
    } catch (error) {
        console.error(`Error seeding data: ${error.message}`);
        console.error(error.stack);
        process.exit(1);
    }
};

const destroyData = async () => {
    try {
        await connectDB();
        await Promise.all([
            User.deleteMany(), Role.deleteMany(), Industry.deleteMany(),
            News.deleteMany(), Vacancy.deleteMany(), Applicant.deleteMany(),
            Media.deleteMany(), Page.deleteMany(), Inquiry.deleteMany(),
            SecurityLog.deleteMany(), Tender.deleteMany()
        ]);
        console.log('Data Destroyed!');
        process.exit();
    } catch (error) {
        console.error(`Error destroying data: ${error.message}`);
        process.exit(1);
    }
};

if (process.argv[2] === '-d') {
    destroyData();
} else {
    importData();
}

