const IndustryDetailPage: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const [industry, setIndustry] = React.useState<Industry | null>(null);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);
    const [isLightboxOpen, setIsLightboxOpen] = React.useState(false);
    const [currentImageIndex, setCurrentImageIndex] = React.useState(0);
    const { t } = useLanguage();

    React.useEffect(() => {
        if (id) {
            const fetchIndustry = async () => {
                try {
                    setLoading(true);
                    const data = await getIndustryById(id);
                    setIndustry(data);
                } catch (err) {
                    setError('Failed to load industry data.');
                } finally {
                    setLoading(false);
                }
            };
            fetchIndustry();
        }
    }, [id]);

    const openLightbox = (index: number) => {
        setCurrentImageIndex(index);
        setIsLightboxOpen(true);
    };

    const closeLightbox = () => setIsLightboxOpen(false);

    const goToNext = React.useCallback(() => {
        if (!industry) return;
        setCurrentImageIndex((prevIndex) => (prevIndex + 1) % industry.gallery.length);
    }, [industry]);

    const goToPrev = React.useCallback(() => {
        if (!industry) return;
        setCurrentImageIndex((prevIndex) => (prevIndex - 1 + industry.gallery.length) % industry.gallery.length);
    }, [industry]);

    React.useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (!isLightboxOpen) return;
            if (e.key === 'Escape') closeLightbox();
            if (e.key === 'ArrowRight') goToNext();
            if (e.key === 'ArrowLeft') goToPrev();
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isLightboxOpen, goToNext, goToPrev]);

    if (loading) {
        return <div className="flex justify-center items-center h-screen"><Loader /></div>;
    }

    if (error || !industry) {
        return (
            <div className="container mx-auto px-6 py-20 text-center">
                <h1 className="text-4xl font-bold text-white font-montserrat">{t('industryDetailPage.errorTitle', 'Industry Not Found')}</h1>
                <p className="mt-4 text-[#effefb] font-lato">{t('industryDetailPage.errorText', 'The industry group you are looking for does not exist or could not be loaded.')}</p>
                <Link to="/industry" className="mt-8 inline-block from-[#41737c] to-[#2D4F54] text-white font-bold py-3 px-8 rounded-md btn-hover-effect font-roboto-condensed">
                    {t('industryDetailPage.errorButton', 'Back to Industries')}
                </Link>
            </div>
        );
    }

    return (
        <div className="bg-[#1E2B2B]">
            <HeroSection industry={industry} />

            <Section id="about" titleKey="industryDetailPage.aboutTitle" defaultTitle="About the Industry" className="bg-[#063a3c]">
                <AboutSection industry={industry} />
            </Section>

            <Section id="capabilities" titleKey="industryDetailPage.coreCapabilitiesTitle" defaultTitle="Core Capabilities">
                <CapabilitiesSection industry={industry} />
            </Section>

            <Section id="products" titleKey="industryDetailPage.productsSolutionsTitle" defaultTitle="Products & Solutions" className="bg-[#063a3c]">
                <ProductsSection industry={industry} />
            </Section>

            <Section id="technology" titleKey="industryDetailPage.techInnovationTitle" defaultTitle="Technology & Innovation">
                <TechInnovationSection industry={industry} />
            </Section>

            <Section id="quality" titleKey="industryDetailPage.qualityComplianceTitle" defaultTitle="Quality & Compliance" className="bg-[#063a3c]">
                <QualitySection />
            </Section>

            <Section id="facilities" titleKey="industryDetailPage.productionFacilitiesTitle" defaultTitle="Production Facilities">
                <FacilitiesSection industry={industry} />
            </Section>

            <Section id="projects" titleKey="industryDetailPage.projectsAchievementsTitle" defaultTitle="Projects & Achievements" className="bg-[#063a3c]">
                <ProjectsSection />
            </Section>

            <Section id="leadership" titleKey="industryDetailPage.leadershipTitle" defaultTitle="Leadership & Management Team">
                <LeadershipSection industry={industry} />
            </Section>

            <Section id="news" titleKey="industryDetailPage.newsUpdatesTitle" defaultTitle="News & Updates" className="bg-[#063a3c]">
                <NewsSection industry={industry} />
            </Section>

            <Section id="gallery" titleKey="industryDetailPage.galleryTitle" defaultTitle="Gallery / Media Center">
                <GallerySection industry={industry} onImageClick={openLightbox} />
            </Section>

            <Section id="downloads" titleKey="industryDetailPage.downloadsTitle" defaultTitle="Downloads" className="bg-[#063a3c]">
                <DownloadsSection />
            </Section>

            <Section id="contact" titleKey="industryDetailPage.contactTitle" defaultTitle="Contact Information">
                <ContactSection industry={industry} />
            </Section>

            {/* Lightbox Modal */}
            {isLightboxOpen && (
                <div 
                    className="fixed inset-0 bg-black bg-opacity-80 z-[100] flex items-center justify-center animate-fade-in"
                    onClick={closeLightbox} role="dialog" aria-modal="true" aria-labelledby="lightbox-title">
                    <div className="relative w-full h-full max-w-5xl max-h-[90vh] p-4" onClick={(e) => e.stopPropagation()}>
                        <button onClick={closeLightbox} className="absolute -top-2 -right-2 md:top-0 md:right-0 z-20 text-white bg-[#1E2B2B] rounded-full p-2 hover:bg-opacity-80 transition-opacity" aria-label="Close image viewer">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                        <button onClick={goToPrev} className="absolute left-0 md:-left-12 top-1/2 -translate-y-1/2 z-20 text-white bg-[#1E2B2B] rounded-full p-2 hover:bg-opacity-80 transition-opacity" aria-label="Previous image">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg>
                        </button>
                        <button onClick={goToNext} className="absolute right-0 md:-right-12 top-1/2 -translate-y-1/2 z-20 text-white bg-[#1E2B2B] rounded-full p-2 hover:bg-opacity-80 transition-opacity" aria-label="Next image">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" /></svg>
                        </button>
                        <div className="relative w-full h-full flex flex-col items-center justify-center">
                            <img src={industry.gallery[currentImageIndex]} alt={`${industry.name} gallery image ${currentImageIndex + 1}`} className="max-w-full max-h-full object-contain rounded-md shadow-lg" />
                            <div id="lightbox-title" className="absolute bottom-2 bg-black/50 text-white text-sm px-3 py-1 rounded-md">
                                {currentImageIndex + 1} / {industry.gallery.length}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

