import '../../../types';
import React, { useState, useMemo, useEffect } from 'react';
import { getVacancies, createVacancy, updateVacancy, deleteVacancy } from '../../../services/api';
import Card from '../ui/Card';
import Table from '../ui/Table';
import Button from '../ui/Button';
import Tag from '../ui/Tag';
import ApplicantTracker from './ApplicantTracker';
import type { Vacancy, VacancyStatus, VacancyType, Division } from '../../../types';
import { useToast } from '../../../App';

const VacancyFormModal: React.FC<{
    vacancy: Partial<Vacancy> | null;
    onClose: () => void;
    onSave: (vacancy: Partial<Vacancy>) => void;
}> = ({ vacancy, onClose, onSave }) => {
    const [formData, setFormData] = useState(vacancy || {});

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(formData);
    };

    return (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-lg shadow-xl w-full max-w-2xl">
                <form onSubmit={handleSubmit}>
                    <div className="p-6 border-b">
                        <h3 className="text-xl font-bold">{vacancy?.id ? 'Edit' : 'Create'} Vacancy</h3>
                    </div>
                    <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
                        <input name="title" value={formData.title || ''} onChange={handleChange} placeholder="Job Title" className="w-full border-gray-300 rounded-md p-2" required />
                        <textarea name="description" value={formData.description || ''} onChange={handleChange} placeholder="Description" className="w-full border-gray-300 rounded-md p-2" rows={3} required />
                        <div className="grid grid-cols-2 gap-4">
                            <input name="location" value={formData.location || ''} onChange={handleChange} placeholder="Location" className="w-full border-gray-300 rounded-md p-2" required />
                            <input type="date" name="closingDate" value={formData.closingDate ? formData.closingDate.split('T')[0] : ''} onChange={handleChange} className="w-full border-gray-300 rounded-md p-2" required />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                           <select name="type" value={formData.type || ''} onChange={handleChange} className="w-full border-gray-300 rounded-md p-2" required><option value="">Type</option><option>Full-time</option><option>Contract</option></select>
                           <select name="division" value={formData.division || ''} onChange={handleChange} className="w-full border-gray-300 rounded-md p-2" required><option value="">Division</option><option>HAEI</option><option>GAEI</option><option>Corporate</option></select>
                        </div>
                    </div>
                    <div className="p-4 bg-gray-50 flex justify-end gap-2">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit" variant="primary">Save Vacancy</Button>
                    </div>
                </form>
            </div>
        </div>
    );
};

const VacancyManagement: React.FC = () => {
    const [vacancies, setVacancies] = useState<Vacancy[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string|null>(null);
    const [selectedVacancy, setSelectedVacancy] = useState<Vacancy | null>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingVacancy, setEditingVacancy] = useState<Partial<Vacancy> | null>(null);
    const { addToast } = useToast();
    const [filters, setFilters] = useState<{
        division: Division | 'All';
        type: VacancyType | 'All';
        status: VacancyStatus | 'All';
    }>({
        division: 'All',
        type: 'All',
        status: 'All',
    });

    const fetchVacancies = async () => {
        try {
            setLoading(true);
            const data = await getVacancies();
            setVacancies(data);
        } catch (err) {
            setError('Failed to load vacancies.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchVacancies();
    }, []);

    const handleSave = async (vacancy: Partial<Vacancy>) => {
        try {
            if (vacancy.id) {
                await updateVacancy(vacancy.id, vacancy);
                addToast('Vacancy updated successfully', 'success');
            } else {
                await createVacancy(vacancy);
                addToast('Vacancy created successfully', 'success');
            }
            fetchVacancies();
            setIsModalOpen(false);
            setEditingVacancy(null);
        } catch (error) {
            addToast('Failed to save vacancy.', 'error');
        }
    };

    const handleDelete = async (id: string) => {
        if (window.confirm('Are you sure you want to delete this vacancy and all its applicants?')) {
            try {
                await deleteVacancy(id);
                addToast('Vacancy deleted successfully', 'success');
                fetchVacancies();
            } catch (error) {
                addToast('Failed to delete vacancy.', 'error');
            }
        }
    };

    const handleOpenModal = (vacancy?: Vacancy) => {
        setEditingVacancy(vacancy || {});
        setIsModalOpen(true);
    };

    const handleFilterChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
    };

    const filteredVacancies = useMemo(() => {
        return vacancies.filter(vacancy => {
            const { division, type, status } = filters;
            return (
                (division === 'All' || vacancy.division === division) &&
                (type === 'All' || vacancy.type === type) &&
                (status === 'All' || vacancy.status === status)
            );
        });
    }, [vacancies, filters]);

    const filterOptions = useMemo(() => {
        const divisions: (Division | 'All')[] = ['All', ...Array.from(new Set(vacancies.map(v => v.division)))];
        const types: (VacancyType | 'All')[] = ['All', ...Array.from(new Set(vacancies.map(v => v.type)))];
        const statuses: (VacancyStatus | 'All')[] = ['All', ...Array.from(new Set(vacancies.map(v => v.status)))];
        return { divisions, types, statuses };
    }, [vacancies]);

    if (selectedVacancy) {
        return <ApplicantTracker vacancy={selectedVacancy} onBack={() => setSelectedVacancy(null)} />;
    }

    const tableHeaders = ['Job Title', 'Division', 'Applicants', 'Status', 'Closing Date', 'Actions'];

    return (
        <>
        {isModalOpen && <VacancyFormModal vacancy={editingVacancy} onClose={() => setIsModalOpen(false)} onSave={handleSave} />}
        <Card>
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h2 className="text-xl text-[#1E2B2B] font-montserrat">Manage Vacancies</h2>
                <div className="flex items-center gap-2">
                    <Button variant="secondary">Export CSV</Button>
                    <Button variant="primary" onClick={() => handleOpenModal()}>Post New Vacancy</Button>
                </div>
            </div>

            <Card bodyClassName="!p-4" className="bg-[#effefb] mb-6">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-center">
                    <h3 className="text-md font-bold text-[#1E2B2B] font-roboto-condensed md:text-right">Filter By:</h3>
                     <select name="division" value={filters.division} onChange={handleFilterChange} className="bg-white border-gray-300 text-[#1E2B2B] text-sm rounded-md focus:ring-[#41737c] focus:border-[#41737c] w-full p-2">
                        {filterOptions.divisions.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                     <select name="type" value={filters.type} onChange={handleFilterChange} className="bg-white border-gray-300 text-[#1E2B2B] text-sm rounded-md focus:ring-[#41737c] focus:border-[#41737c] w-full p-2">
                        {filterOptions.types.map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                    <select name="status" value={filters.status} onChange={handleFilterChange} className="bg-white border-gray-300 text-[#1E2B2B] text-sm rounded-md focus:ring-[#41737c] focus:border-[#41737c] w-full p-2">
                        {filterOptions.statuses.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>
            </Card>

            <Table headers={tableHeaders}>
                {loading && <tr><td colSpan={6} className="text-center p-4">Loading...</td></tr>}
                {error && <tr><td colSpan={6} className="text-center p-4 text-red-500">{error}</td></tr>}
                {!loading && filteredVacancies.map(vacancy => (
                    <tr key={vacancy.id} className="odd:bg-white even:bg-[#effefb] hover:bg-gray-50">
                        <td className="px-6 py-4 whitespace-nowrap">
                            <div className="font-semibold text-[#1E2B2B]">{vacancy.title}</div>
                            <div className="text-xs text-gray-500">{vacancy.location}</div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-gray-700">{vacancy.division}</td>
                        <td className="px-6 py-4 whitespace-nowrap text-center text-[#1E2B2B] font-semibold">{vacancy.applicantCount}</td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <Tag status={vacancy.status as any} />
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-gray-700">{new Date(vacancy.closingDate).toLocaleDateString()}</td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center space-x-2">
                                <Button variant="secondary" size="sm" onClick={() => setSelectedVacancy(vacancy)}>
                                    View Applicants
                                </Button>
                                <Button variant="icon" size="sm" title="Edit Vacancy" onClick={() => handleOpenModal(vacancy)}>
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"></path></svg>
                                </Button>
                                <Button variant="icon" size="sm" title="Delete" className="text-red-500 hover:bg-red-100" onClick={() => handleDelete(vacancy.id)}>
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                                </Button>
                            </div>
                        </td>
                    </tr>
                ))}
            </Table>
        </Card>
        </>
    );
};

export default VacancyManagement;

// FIX: Reordered imports to ensure global JSX namespace augmentation from `types.ts` is applied before React is imported. This resolves errors where standard HTML elements were not recognized in JSX.
import '../../../types';
import React, { useState, useEffect } from 'react';
import { getInquiries, updateInquiry } from '../../../services/api';
import type { ContactInquiry, InquiryStatus } from '../../../types';
import Card from '../ui/Card';
import Table from '../ui/Table';
import Button from '../ui/Button';
import Checkbox from '../ui/Checkbox';
import { useToast } from '../../../App';

const InquiryStatusTag: React.FC<{ status: InquiryStatus }> = ({ status }) => {
    const statusStyles: { [key in InquiryStatus]: string } = {
        Unread: 'bg-blue-100 text-blue-800',
        Read: 'bg-purple-100 text-purple-800',
        Resolved: 'bg-green-100 text-green-800',
    };
    return (
        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${statusStyles[status]}`}>
            <svg className="-ml-0.5 mr-1.5 h-2 w-2" fill="currentColor" viewBox="0 0 8 8">
                <circle cx="4" cy="4" r="3" />
            </svg>
            {status}
        </span>
    );
};

const InquiryManagement: React.FC = () => {
    const [inquiries, setInquiries] = useState<ContactInquiry[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedInquiries, setSelectedInquiries] = useState<Set<string>>(new Set());
    const [filter, setFilter] = useState<InquiryStatus | 'All'>('All');
    const { addToast } = useToast();

    const fetchInquiries = async () => {
        try {
            setLoading(true);
            const data = await getInquiries();
            setInquiries(data);
        } catch (error) {
            addToast('Failed to load inquiries.', 'error');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchInquiries();
    }, []);

    const filteredInquiries = inquiries.filter(inquiry => filter === 'All' || inquiry.status === filter);

    const handleSelectionChange = (inquiryId: string) => {
        setSelectedInquiries(prev => {
            const newSelection = new Set(prev);
            if (newSelection.has(inquiryId)) {
                newSelection.delete(inquiryId);
            } else {
                newSelection.add(inquiryId);
            }
            return newSelection;
        });
    };

    const handleSelectAll = (event: React.ChangeEvent<HTMLInputElement>) => {
        if (event.target.checked) {
            setSelectedInquiries(new Set(filteredInquiries.map(i => i.id)));
        } else {
            setSelectedInquiries(new Set());
        }
    };

    const handleBulkUpdate = async (status: InquiryStatus) => {
        const ids = Array.from(selectedInquiries);
        try {
            await Promise.all(ids.map(id => updateInquiry(id, { status })));
            addToast(`${ids.length} inquiries updated to ${status}.`, 'success');
            fetchInquiries();
            setSelectedInquiries(new Set());
        } catch (error) {
            addToast('Failed to update inquiries.', 'error');
        }
    };

    const isAllSelected = selectedInquiries.size === filteredInquiries.length && filteredInquiries.length > 0;
    const isIndeterminate = selectedInquiries.size > 0 && selectedInquiries.size < filteredInquiries.length;

    const headers = [
        <Checkbox key="select-all" checked={isAllSelected} indeterminate={isIndeterminate} onChange={handleSelectAll} />,
        'Sender',
        'Subject',
        'Status',
        'Received',
        'Assigned To',
        'Actions'
    ];

    return (
         <Card>
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h2 className="text-xl text-[#1E2B2B] font-montserrat">Contact Inquiries</h2>
                 <div className="flex items-center gap-2">
                    <input type="text" placeholder="Search inquiries..." className="bg-white border-gray-300 rounded-md py-1.5 px-3 text-[#1E2B2B] text-sm focus:outline-none focus:border-[#41737c] focus:ring-1 focus:ring-[#41737c]" />
                    <select value={filter} onChange={(e) => setFilter(e.target.value as InquiryStatus | 'All')} className="bg-white border-gray-300 text-[#1E2B2B] text-sm rounded-md focus:ring-[#41737c] focus:border-[#41737c] py-1.5">
                        <option value="All">All Statuses</option>
                        <option value="Unread">Unread</option>
                        <option value="Read">Read</option>
                        <option value="Resolved">Resolved</option>
                    </select>
                </div>
            </div>

            {selectedInquiries.size > 0 && (
                <div className="bg-[#effefb] p-3 rounded-md mb-4 flex items-center justify-between border border-[#c2f2f2]">
                    <span className="text-sm text-gray-600">{selectedInquiries.size} selected</span>
                    <div className="flex items-center gap-2">
                        <Button variant="secondary" size="sm" onClick={() => handleBulkUpdate('Read')}>Mark as Read</Button>
                        <Button variant="secondary" size="sm" onClick={() => handleBulkUpdate('Resolved')}>Mark as Resolved</Button>
                    </div>
                </div>
            )}

            <Table headers={headers}>
                {loading ? <tr><td colSpan={7} className="text-center p-4">Loading...</td></tr> : 
                filteredInquiries.map(inquiry => (
                    <tr key={inquiry.id} className={`hover:bg-gray-50 ${selectedInquiries.has(inquiry.id) ? 'bg-teal-50' : 'odd:bg-white even:bg-[#effefb]'}`}>
                        <td className="px-6 py-4 w-12">
                            <Checkbox checked={selectedInquiries.has(inquiry.id)} onChange={() => handleSelectionChange(inquiry.id)} />
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <div className="font-semibold text-[#1E2B2B]">{inquiry.name}</div>
                            <div className="text-xs text-gray-500">{inquiry.email}</div>
                        </td>
                         <td className="px-6 py-4">
                            <div className="font-semibold text-[#1E2B2B] truncate max-w-xs">{inquiry.subject}</div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <InquiryStatusTag status={inquiry.status} />
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-gray-700">{new Date(inquiry.receivedAt).toLocaleDateString()}</td>
                         <td className="px-6 py-4 whitespace-nowrap text-gray-700">{inquiry.assignedTo || 'N/A'}</td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <Button variant="icon" size="sm" title="View Inquiry">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>
                            </Button>
                        </td>
                    </tr>
                ))}
            </Table>
        </Card>
    );
};

export default InquiryManagement;

import * as React from 'react';
