const { Sequelize } = require('sequelize');

const sequelize = new Sequelize(
  process.env.DB_NAME || 'deig_db',
  process.env.DB_USER || 'postgres',
  process.env.DB_PASS || 'password',
  {
    host: process.env.DB_HOST || 'localhost',
    dialect: 'postgres',
    logging: false,
  }
);

const connectDB = async () => {
  try {
    await sequelize.authenticate();
    console.log(`\n✅ PostgreSQL Connected Successfully`);
    console.log(`   Host: ${process.env.DB_HOST || 'localhost'}`);
    console.log(`   Database: ${process.env.DB_NAME || 'deig_db'}`);

    // Sync models
    await sequelize.sync({ alter: true });
    console.log('   Models Synced\n');
  } catch (error) {
    console.error('\n❌ Database Connection Error:', error.message);

    if (error.message.includes('password authentication failed')) {
      console.error('\n>>> CRITICAL FIX NEEDED:');
      console.error('>>> The backend cannot login to PostgreSQL. You must create a .env file.');
      console.error('>>> File Path: deig-admin-backend/.env');
      console.error('>>> Content:');
      console.error('    PORT=5001');
      console.error('    DB_NAME=deig_db');
      console.error('    DB_USER=postgres');
      console.error('    DB_PASS=YOUR_ACTUAL_POSTGRES_PASSWORD_HERE');
    } else if (error.message.includes('does not exist')) {
        console.error(`\n>>> FIX: Database "${process.env.DB_NAME || 'deig_db'}" does not exist.`);
        console.error('>>> Run this SQL command in pgAdmin or psql:');
        console.error(`    CREATE DATABASE ${process.env.DB_NAME || 'deig_db'};`);
    }

    process.exit(1);
  }
};

module.exports = { sequelize, connectDB };

const { News, User } = require('../models');

// @desc    Get all news articles
const getAllNews = async (req, res) => {
  try {
    const news = await News.findAll({
        order: [['date', 'DESC']],
        include: { model: User, as: 'author', attributes: ['name'] }
    });
    res.status(200).json(news);
  } catch (error) {
    res.status(500).json({ message: 'Server error fetching news articles', error: error.message });
  }
};

// @desc    Create a news article
const createNews = async (req, res) => {
  const { title, excerpt, imageUrl, category, date } = req.body;
  try {
    const newArticle = await News.create({
        title,
        excerpt,
        imageUrl,
        category,
        date: date || new Date(),
        status: 'Draft',
        authorId: req.user.id,
    });
    res.status(201).json(newArticle);
  } catch (error) {
    res.status(500).json({ message: 'Server error creating news article', error: error.message });
  }
};

// @desc    Update a news article
const updateNews = async (req, res) => {
    try {
        const article = await News.findByPk(req.params.id);
        if (article) {
            await article.update(req.body);
            res.status(200).json(article);
        } else {
            res.status(404).json({ message: 'News article not found' });
        }
    } catch (error) {
        res.status(500).json({ message: 'Server error updating news article', error: error.message });
    }
};

// @desc    Delete a news article
const deleteNews = async (req, res) => {
    try {
        const article = await News.findByPk(req.params.id);
        if (article) {
            await article.destroy();
            res.status(200).json({ message: 'News article removed' });
        } else {
            res.status(404).json({ message: 'News article not found' });
        }
    } catch (error) {
        res.status(500).json({ message: 'Server error deleting news article', error: error.message });
    }
};

module.exports = {
  getAllNews,
  createNews,
  updateNews,
  deleteNews,
};

