// --- API HELPER ---
const apiHelper = async (endpoint: string, options: RequestInit = {}) => {
    const token = localStorage.getItem('deig-admin-token');
    const headers = {
        ...options.headers,
    };

    if (token) {
        (headers as Record<string, string>)['Authorization'] = `Bearer ${token}`;
    }

    if (!(options.body instanceof FormData)) {
        (headers as Record<string, string>)['Content-Type'] = 'application/json';
    }

    try {
        // Simple timeout to fail fast if backend is down (e.g., 2 seconds)
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 2000);

        const response = await fetch(`${API_BASE_URL}${endpoint}`, {
            ...options,
            headers,
            signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
            const errorData = await response.json().catch(() => ({ message: 'An unknown error occurred' }));
            throw new Error(errorData.message || `API error: ${response.statusText}`);
        }

        // Handle responses with no content
        if (response.status === 204) {
            return null;
        }

        return response.json();
    } catch (error) {
        console.warn(`API Call Failed to ${API_BASE_URL}${endpoint}. Falling back to mock data if available.`, error);
        throw error;
    }
};


