const SunIcon = () => (
    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M12 12a5 5 0 100-10 5 5 0 000 10z"></path></svg>
);

const MoonIcon = () => (
    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"></path></svg>
);

const ThemeToggle: React.FC = () => {
    const { theme, setTheme } = useTheme();
    const [isMounted, setIsMounted] = React.useState(false);

    React.useEffect(() => {
        setIsMounted(true);
    }, []);

    const toggleTheme = () => {
        setTheme(theme === 'dark' ? 'light' : 'dark');
    };

    if (!isMounted) {
        return <div className="w-8 h-8" />; 
    }

    return (
        <button
            onClick={toggleTheme}
            className="p-2 rounded-full text-gray-700 dark:text-[#f1d1aa] hover:bg-gray-200 dark:hover:bg-white/10 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-white dark:focus:ring-offset-[#084d4f] focus:ring-[#41737c]"
            aria-label="Toggle theme"
        >
            {theme === 'dark' ? <SunIcon /> : <MoonIcon />}
        </button>
    );
};

const Header: React.FC = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = React.useState(false);
  const [isIndustryDropdownOpen, setIsIndustryDropdownOpen] = React.useState(false);
  const [isScrolled, setIsScrolled] = React.useState(false);
  const [industries, setIndustries] = React.useState<Industry[]>([]);
  const { language, setLanguage, t } = useLanguage();

  React.useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);

    const fetchIndustries = async () => {
        try {
            const data = await getIndustries();
            setIndustries(data);
        } catch (error) {
            console.error("Failed to fetch industries for header:", error);
        }
    };
    fetchIndustries();

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const activeLinkStyle = {
    borderBottomColor: '#bf8464',
  };

  const mobileActiveLinkStyle = {
    color: '#bf8464',
    fontWeight: 'bold',
  };

  const navLinkClass = "py-2 px-3 text-gray-700 dark:text-white transition-colors duration-300 font-roboto-condensed border-b-2 border-transparent hover:border-[#bf8464]";

  return (
    <header className={`sticky top-0 z-50 transition-all duration-300 ${isScrolled ? 'dark:bg-[#084d4f]/95 bg-white/95 shadow-lg dark:shadow-black/30 shadow-black/10 backdrop-blur-sm' : 'bg-transparent'}`}>
      <nav className="container mx-auto px-6 py-4">
        <div className="flex items-center justify-between">
          <Link to="/" className="text-2xl font-black text-gray-800 dark:text-white uppercase tracking-wider font-montserrat">
            DEIG
          </Link>

          {/* Desktop Menu */}
          <div className="hidden md:flex items-center space-x-1">
            <NavLink to="/" className={navLinkClass} style={({ isActive }) => isActive ? activeLinkStyle : {}}>{t('header.home', 'Home')}</NavLink>
            <NavLink to="/about" className={navLinkClass} style={({ isActive }) => isActive ? activeLinkStyle : {}}>{t('header.about', 'About')}</NavLink>
            <div className="relative" onMouseEnter={() => setIsIndustryDropdownOpen(true)} onMouseLeave={() => setIsIndustryDropdownOpen(false)}>
              <NavLink to="/industry" className={navLinkClass} style={({ isActive }) => isActive ? activeLinkStyle : {}}>
                {t('header.industry', 'Industry')}
