import '../../../types';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    children: React.ReactNode;
    variant?: 'primary' | 'secondary' | 'icon';
    size?: 'sm' | 'md' | 'lg';
}

const Button: React.FC<ButtonProps> = ({ children, variant = 'primary', size = 'md', className = '', ...props }) => {
    const baseStyles = 'inline-flex items-center justify-center font-semibold rounded-md focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-white transition-all duration-200';

    const variantStyles = {
        primary: 'bg-brand-blue text-white hover:bg-[#0d5a94] focus:ring-brand-blue shadow-sm',
        secondary: 'bg-white text-brand-blue border border-brand-blue hover:bg-[#F0F9FF] focus:ring-brand-blue',
        icon: 'text-gray-500 hover:bg-gray-100 hover:text-brand-blue focus:ring-brand-blue',
    };

    const sizeStyles = {
        sm: `px-2 py-1 text-xs ${variant === 'icon' ? 'p-1.5' : ''}`,
        md: `px-4 py-2 text-sm ${variant === 'icon' ? 'p-2' : ''}`,
        lg: `px-6 py-3 text-base ${variant === 'icon' ? 'p-3' : ''}`,
    };

    const combinedClassName = `${baseStyles} ${variantStyles[variant]} ${sizeStyles[size]} ${className}`;

    return (
        <button className={combinedClassName} {...props}>
            {children}
        </button>
    );
};

export default Button;

