import * as React from 'react';
// FIX: Add import for `types.ts` to ensure global JSX namespace augmentation is applied correctly, resolving errors where standard HTML elements were not recognized in JSX.
import '../../../types';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    children: React.ReactNode;
    variant?: 'primary' | 'secondary' | 'icon';
    size?: 'sm' | 'md' | 'lg';
}

const Button: React.FC<ButtonProps> = ({ children, variant = 'primary', size = 'md', className = '', ...props }) => {
    const baseStyles = 'inline-flex items-center justify-center font-semibold rounded-md focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-white transition-all duration-200';

    const variantStyles = {
        // Primary: Base #1172BA, Hover #0C568C (Dark-1), Focus #1172BA
        primary: 'bg-brand-blue-500 text-white hover:bg-brand-blue-600 active:bg-brand-blue-800 focus:ring-brand-blue-500 shadow-sm',
        // Secondary: Base Border Blue, Text Blue, Hover Light-3 #D3E7F6
        secondary: 'bg-white text-brand-blue-500 border border-brand-blue-500 hover:bg-brand-blue-50 focus:ring-brand-blue-500',
        icon: 'text-gray-500 hover:bg-gray-100 hover:text-brand-blue-600 focus:ring-brand-blue-500',
    };

    const sizeStyles = {
        sm: `px-2 py-1 text-xs ${variant === 'icon' ? 'p-1.5' : ''}`,
        md: `px-4 py-2 text-sm ${variant === 'icon' ? 'p-2' : ''}`,
        lg: `px-6 py-3 text-base ${variant === 'icon' ? 'p-3' : ''}`,
    };

    const combinedClassName = `${baseStyles} ${variantStyles[variant]} ${sizeStyles[size]} ${className}`;

    return (
        <button className={combinedClassName} {...props}>
            {children}
        </button>
    );
};

export default Button;

