  return (
    <input
      ref={ref}
      type="checkbox"
      className={`h-4 w-4 rounded bg-gray-200 border-gray-300 text-brand-blue-500 focus:ring-brand-blue-500 focus:ring-offset-white ${className}`}
      {...props}
    />
  );
};

