const ContactSection: React.FC<{ industry: Industry }> = ({ industry }) => {
    const { t } = useLanguage();
    const { addToast } = useToast();
    const [isSubmitting, setIsSubmitting] = React.useState(false);

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSubmitting(true);
        const formData = new FormData(e.currentTarget);
        const data = {
            name: formData.get('name') as string,
            email: formData.get('email') as string,
            subject: `Inquiry for ${industry.acronym}: ${formData.get('subject') as string}`,
            message: formData.get('message') as string,
        };

        try {
            await createInquiry(data);
            addToast(t('contactPage.form.success', 'Your message has been sent successfully!'), 'success');
            (e.target as HTMLFormElement).reset();
        } catch (error) {
            console.error('Inquiry submission failed:', error);
