import '../types';
import * as React from 'react';
import { AnimatedSection } from '../components/AnimatedComponents';
import { getTenders } from '../services/api';
import type { Tender, TenderCategory, TenderStatus } from '../types';
import Loader from '../components/Loader';

const TenderCard: React.FC<{ tender: Tender }> = ({ tender }) => {
    const statusColor = {
        Open: 'bg-brand-green-500 text-white',
        Closed: 'bg-brand-blue-200 text-brand-blue-800',
        Awarded: 'bg-gray-500 text-white',
    };

    return (
        <div className="bg-brand-blue-50 text-brand-blue-900 p-6 rounded-md shadow-lg card-hover-effect flex flex-col h-full border-2 border-transparent hover:border-brand-green-500">
            <div>
                <div className="flex justify-between items-start mb-2">
                    <h3 className="text-xl font-bold text-brand-blue-900 font-roboto-condensed card-title">{tender.title}</h3>
                    <span className={`text-xs font-bold px-3 py-1 rounded-full ${statusColor[tender.status]}`}>{tender.status}</span>
                </div>
                <p className="text-brand-blue-900/80 font-semibold font-roboto-condensed">Tender ID: {tender.id}</p>
                <div className="flex flex-wrap gap-2 mt-3 text-xs font-semibold">
                    <span className="bg-brand-blue-100 text-brand-blue-600 px-2 py-1 rounded-full">{tender.category}</span>
                </div>
                 <div className="text-sm text-brand-blue-900/70 mt-3 font-lato space-y-1">
                    <p><strong>Published:</strong> {new Date(tender.publishedDate).toLocaleDateString()}</p>
                    <p><strong>Closing:</strong> {new Date(tender.closingDate).toLocaleDateString()}</p>
                </div>
            </div>
            <p className="mt-4 text-brand-blue-900/90 font-lato flex-grow text-sm">{tender.summary}</p>
            <button className="mt-6 bg-brand-blue-500 hover:bg-brand-blue-600 text-white font-bold py-2 px-4 rounded-md transition-colors duration-300 font-roboto-condensed btn-hover-effect self-start">
                View Details
            </button>
        </div>
    );
};

const TendersPage: React.FC = () => {
    const [tenders, setTenders] = React.useState<Tender[]>([]);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);
    const [filters, setFilters] = React.useState<{ category: TenderCategory | 'All'; status: TenderStatus | 'All' }>({
        category: 'All',
        status: 'All',
    });

    React.useEffect(() => {
        const fetchTendersData = async () => {
            try {
                setLoading(true);
                const data = await getTenders();
                setTenders(data);
            } catch (err) {
                setError('Failed to load tenders.');
            } finally {
                setLoading(false);
            }
        };
        fetchTendersData();
    }, []);

    const handleFilterChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const { name, value } = e.target;
        if (name === 'category') {
            setFilters(prev => ({ ...prev, category: value as TenderCategory | 'All' }));
        } else if (name === 'status') {
            setFilters(prev => ({ ...prev, status: value as TenderStatus | 'All' }));
        }
    };

    const filterOptions = React.useMemo(() => {
        const categories: (TenderCategory | 'All')[] = ['All', ...Array.from(new Set(tenders.map(t => t.category))) as TenderCategory[]];
        const statuses: (TenderStatus | 'All')[] = ['All', ...Array.from(new Set(tenders.map(t => t.status))) as TenderStatus[]];
        return { categories, statuses };
    }, [tenders]);

    const filteredTenders = React.useMemo(() => {
        return tenders.filter(tender => {
            const { category, status } = filters;
            return (
                (category === 'All' || tender.category === category) &&
                (status === 'All' || tender.status === status)
            );
        });
    }, [tenders, filters]);

    return (
        <div className="bg-transparent">
            <header className="bg-brand-blue-900/60 py-16">
                <div className="container mx-auto px-6 text-center">
                    <h1 className="text-4xl font-black text-white font-montserrat">Tenders</h1>
                    <p className="mt-2 text-lg text-brand-blue-50/80 font-roboto-condensed">
                        Current procurement opportunities and calls for tender.
                    </p>
                </div>
            </header>

            <section className="py-20 bg-brand-blue-900">
                <div className="container mx-auto px-6">
                    <AnimatedSection>
                         <div className="bg-brand-blue-800 p-4 rounded-md mb-12 grid grid-cols-1 md:grid-cols-4 gap-4 items-center">
                            <h3 className="text-lg font-bold text-white font-roboto-condensed md:text-right">Filter By:</h3>
                            <select name="category" value={filters.category} onChange={handleFilterChange} className="bg-brand-blue-900 border border-brand-blue-700 text-white text-sm rounded-md focus:ring-brand-green-500 focus:border-brand-green-500 w-full p-2">
                                {filterOptions.categories.map(c => <option key={c} value={c}>{c}</option>)}
                            </select>
                            <select name="status" value={filters.status} onChange={handleFilterChange} className="bg-brand-blue-900 border border-brand-blue-700 text-white text-sm rounded-md focus:ring-brand-green-500 focus:border-brand-green-500 w-full p-2">
                                {filterOptions.statuses.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                         </div>
                    </AnimatedSection>

                    <div className="space-y-8">
                        {loading && <div className="flex justify-center"><Loader /></div>}
                        {error && <p className="text-center text-red-400">{error}</p>}
                        {!loading && !error && (
                             <>
                                {filteredTenders.length > 0 ? (
                                    filteredTenders.map((tender, index) => (
                                        <AnimatedSection key={tender.id} delay={index * 100}>
                                            <TenderCard tender={tender} />
                                        </AnimatedSection>
                                    ))
                                ) : (
                                    <AnimatedSection>
                                        <div className="text-center py-16 bg-brand-blue-800/50 rounded-md">
                                            <h3 className="text-2xl font-bold text-white font-montserrat">No Tenders Found</h3>
                                            <p className="mt-2 text-brand-blue-50/80 font-lato">There are no tenders matching your current filters. Please check back later.</p>
                                        </div>
                                    </AnimatedSection>
                                )}
                            </>
                        )}
                    </div>
                </div>
            </section>
        </div>
    );
};

export default TendersPage;

