const NewsPage: React.FC = () => {
    const { t } = useLanguage();
    const [articles, setArticles] = React.useState<NewsArticle[]>([]);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);
    const [searchTerm, setSearchTerm] = React.useState('');
    const [selectedCategory, setSelectedCategory] = React.useState<NewsCategory | 'All'>('All');

    React.useEffect(() => {
        const fetchNewsData = async () => {
            try {
                setLoading(true);
                const data = await getNews();
                setArticles(data);
            } catch (err) {
                setError('Failed to load news articles.');
            } finally {
                setLoading(false);
            }
        };
        fetchNewsData();
    }, []);

    const filteredArticles = React.useMemo(() => {
        return articles.filter(article => {
            const matchesCategory = selectedCategory === 'All' || article.category === selectedCategory;
            const matchesSearch = searchTerm === '' ||
                article.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                article.excerpt.toLowerCase().includes(searchTerm.toLowerCase());
            return matchesCategory && matchesSearch;
        });
    }, [articles, searchTerm, selectedCategory]);

    // Get top 5 articles for the slider
    const featuredArticles = articles.slice(0, 5);
    const pressReleases = articles.filter(a => a.category === 'Press Release').slice(0, 4);

    return (
        <div className="bg-transparent">
            {/* Page Header */}
            <header className="bg-brand-blue-900/60 py-16">
                <div className="container mx-auto px-6 text-center">
                    <h1 className="text-4xl font-black text-white font-montserrat">{t('newsPage.title', 'News & Updates')}</h1>
                    <p className="mt-2 text-lg text-brand-blue-50/80 font-roboto-condensed">
                        {t('newsPage.subtitle', 'Latest announcements, press releases, and industrial updates.')}
                    </p>
                </div>
            </header>

            {loading ? <div className="py-20 flex justify-center"><Loader /></div> :
             error ? <p className="py-20 text-center text-red-400">{error}</p> :
             <>
                {/* Replaced single article prop with array of articles for slider */}
                <FeaturedNewsSlider articles={featuredArticles} />

                <Section id="latest-news-feed" title={t('newsPage.latestNewsTitle', 'Latest News Feed')} className="bg-brand-blue-800/30">
                    <div className="max-w-7xl mx-auto">
                        {/* Filters and Search */}
                        <AnimatedSection>
                            <div className="flex flex-col md:flex-row gap-4 justify-between items-center mb-8">
                                <div className="flex-grow w-full md:w-auto">
                                    <input 
                                        type="search" 
                                        value={searchTerm}
                                        onChange={(e) => setSearchTerm(e.target.value)}
                                        placeholder={t('newsPage.searchPlaceholder', 'Search news articles...')}
                                        className="w-full bg-brand-blue-900 border border-brand-blue-700 rounded-md py-2 px-4 text-white placeholder-gray-400 focus:outline-none focus:border-brand-green-500"
                                    />
                                </div>
                                 <div className="flex items-center space-x-2 overflow-x-auto pb-2">
                                    <button onClick={() => setSelectedCategory('All')} className={`px-4 py-1.5 text-sm font-semibold rounded-md transition-colors whitespace-nowrap ${selectedCategory === 'All' ? 'bg-brand-green-600 text-white' : 'bg-brand-blue-800 text-white hover:bg-brand-blue-700'}`}>{t('newsPage.allCategories', 'All')}</button>
                                    {categories.map(cat => (
                                         <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-4 py-1.5 text-sm font-semibold rounded-md transition-colors whitespace-nowrap ${selectedCategory === cat ? 'bg-brand-green-600 text-white' : 'bg-brand-blue-800 text-white hover:bg-brand-blue-700'}`}>{cat}</button>
                                    ))}
                                </div>
                            </div>
                        </AnimatedSection>

                        {/* News Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                            {filteredArticles.length > 0 ? (
                                filteredArticles.map((article, index) => (
                                    <AnimatedSection key={article.id} delay={index * 100}>
