                        </div>
                    </div>
                </Section>

                <Section id="press-releases" title={t('newsPage.pressReleasesTitle', 'Official Press Releases')} subtitle={t('newsPage.pressReleasesSubtitle', 'Formal statements and announcements from the DEIG corporate office.')} className="bg-brand-blue-900">
                    <div className="max-w-4xl mx-auto bg-brand-blue-800 rounded-md shadow-lg p-2">
                        {pressReleases.map((article, index) => (
                            <AnimatedSection key={article.id} delay={index * 100}>
