                                className="inline-block bg-brand-blue-600 hover:bg-brand-blue-500 text-white font-bold py-3 px-8 rounded-md transition-colors duration-300 font-roboto-condensed self-start shadow-md hover:shadow-lg transform hover:-translate-y-0.5"
                            >
                                {t('newsPage.readMore', 'Read Full Story →')}
                            </Link>
                        </div>
                    </div>

                    {/* Navigation Arrows (Visible on hover or mobile) */}
                    <button 
                        onClick={goToPrev}
                        className="absolute left-4 top-1/2 -translate-y-1/2 bg-black/30 hover:bg-brand-green-600 text-white p-3 rounded-full backdrop-blur-sm transition-all transform hover:scale-110 z-10 focus:outline-none opacity-0 group-hover:opacity-100 duration-300"
                        aria-label="Previous Slide"
                    >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7"></path></svg>
                    </button>
                    <button 
                        onClick={goToNext}
                        className="absolute right-4 top-1/2 -translate-y-1/2 bg-black/30 hover:bg-brand-green-600 text-white p-3 rounded-full backdrop-blur-sm transition-all transform hover:scale-110 z-10 focus:outline-none opacity-0 group-hover:opacity-100 duration-300"
                        aria-label="Next Slide"
                    >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path></svg>
                    </button>

                    {/* Dots Navigation */}
                    <div className="absolute bottom-4 lg:bottom-8 left-0 right-0 flex justify-center space-x-2 z-10">
                        {articles.map((_, index) => (
                            <button
                                key={index}
