                <Section id="newsletter" title={t('newsPage.newsletterTitle', 'Stay Updated')} subtitle={t('newsPage.newsletterSubtitle', 'Subscribe to our newsletter to receive the latest news and updates directly in your inbox.')} className="bg-brand-blue-800/30">
                    <AnimatedSection>
                        <form className="max-w-xl mx-auto flex flex-col sm:flex-row gap-4" onSubmit={e => e.preventDefault()}>
                            <input type="email" placeholder={t('newsPage.newsletterPlaceholder', 'Enter your email address')} className="flex-grow bg-brand-blue-900 border border-brand-blue-700 rounded-md py-3 px-4 text-white placeholder-gray-400 focus:outline-none focus:border-brand-green-500" />
                            <button type="submit" className="bg-brand-green-600 hover:bg-brand-green-700 text-white font-bold py-3 px-6 rounded-md transition-colors font-roboto-condensed">
                                {t('newsPage.newsletterButton', 'Subscribe')}
                            </button>
                        </form>
                    </AnimatedSection>
                </Section>
             </>
            }
        </div>
    );
};

