const FeaturedNewsSlider: React.FC<{ articles: NewsArticle[] }> = ({ articles }) => {
    const { t } = useLanguage();
    const [currentIndex, setCurrentIndex] = React.useState(0);
    const [isPaused, setIsPaused] = React.useState(false);

    // Auto-slide functionality
    React.useEffect(() => {
        if (!articles || articles.length <= 1 || isPaused) return;

        const interval = setInterval(() => {
            setCurrentIndex((prevIndex) => (prevIndex + 1) % articles.length);
        }, 6000); // 6 Seconds per slide

        return () => clearInterval(interval);
    }, [articles, isPaused]);

    const hasArticles = articles && articles.length > 0;
    const currentArticle = hasArticles ? articles[currentIndex] : null;

    const goToNext = () => {
        if (hasArticles) setCurrentIndex((prev) => (prev + 1) % articles.length);
    };

    const goToPrev = () => {
        if (hasArticles) setCurrentIndex((prev) => (prev - 1 + articles.length) % articles.length);
    };

    return (
        <div className="relative pt-24 pb-12 bg-brand-blue-900">
             <div className="container mx-auto px-6">
                <AnimatedSection>
                    {/* Header for the Slider Section */}
                    <div className="text-center mb-10">
                        <h1 className="text-4xl font-black text-white font-montserrat">{t('newsPage.title', 'News & Updates')}</h1>
                        <p className="mt-2 text-lg text-brand-blue-50/80 font-roboto-condensed">
                            {t('newsPage.subtitle', 'Latest announcements, press releases, and industrial updates.')}
                        </p>
                    </div>

                    {hasArticles && currentArticle && (
                        <div 
                            className="relative group bg-brand-blue-800 rounded-md shadow-lg overflow-hidden border border-brand-blue-700 min-h-[500px]"
                            onMouseEnter={() => setIsPaused(true)}
                            onMouseLeave={() => setIsPaused(false)}
                        >
                            {/* Content Container - Uses Key to Trigger Animation on Change */}
                            <div key={currentArticle.id} className="grid grid-cols-1 lg:grid-cols-2 h-full animate-fade-in">
                                {/* Image Side */}
                                <div className="h-64 lg:h-full min-h-[300px] image-container blueprint-overlay relative">
                                    <img 
                                        src={currentArticle.imageUrl} 
                                        alt={currentArticle.title} 
                                        className="w-full h-full object-cover transition-transform duration-700 hover:scale-105" 
                                    />
                                    <div className="absolute top-4 left-4">
                                        <span className="bg-brand-green-600 text-white text-xs font-bold px-3 py-1 rounded-full uppercase tracking-wider shadow-md">
                                            {currentArticle.category}
                                        </span>
                                    </div>
                                </div>

                                {/* Text Side */}
                                <div className="p-8 lg:p-12 flex flex-col justify-center h-full relative bg-brand-blue-800">
                                    <div className="mb-4 text-brand-blue-300 font-roboto-condensed text-sm">
                                        {new Date(currentArticle.date).toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' })}
                                    </div>

                                    <h3 className="text-3xl lg:text-4xl font-bold text-white font-montserrat leading-tight mb-6">
                                        {currentArticle.title}
                                    </h3>

                                    {/* Article Excerpt with proper formatting */}
                                    <div 
                                        className="text-brand-blue-50/90 font-lato text-lg line-clamp-4 whitespace-pre-line prose prose-invert max-w-none mb-8"
                                        dangerouslySetInnerHTML={{ __html: currentArticle.excerpt }}
                                    />

                                    <Link 
                                        to={`/news/${currentArticle.id}`}
                                        className="inline-block bg-brand-blue-600 hover:bg-brand-blue-500 text-white font-bold py-3 px-8 rounded-md transition-colors duration-300 font-roboto-condensed self-start shadow-md hover:shadow-lg transform hover:-translate-y-0.5"
                                    >
                                        {t('newsPage.readMore', 'Read Full Story →')}
                                    </Link>
                                </div>
                            </div>

                            {/* Navigation Arrows (Visible on hover or mobile) */}
                            <button 
                                onClick={goToPrev}
                                className="absolute left-4 top-1/2 -translate-y-1/2 bg-black/30 hover:bg-brand-green-600 text-white p-3 rounded-full backdrop-blur-sm transition-all transform hover:scale-110 z-10 focus:outline-none opacity-0 group-hover:opacity-100 duration-300"
                                aria-label="Previous Slide"
                            >
                                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7"></path></svg>
                            </button>
                            <button 
                                onClick={goToNext}
                                className="absolute right-4 top-1/2 -translate-y-1/2 bg-black/30 hover:bg-brand-green-600 text-white p-3 rounded-full backdrop-blur-sm transition-all transform hover:scale-110 z-10 focus:outline-none opacity-0 group-hover:opacity-100 duration-300"
                                aria-label="Next Slide"
                            >
                                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path></svg>
                            </button>

                            {/* Dots Navigation */}
                            <div className="absolute bottom-4 lg:bottom-8 left-0 right-0 flex justify-center space-x-2 z-10">
                                {articles.map((_, index) => (
                                    <button
                                        key={index}
                                        onClick={() => setCurrentIndex(index)}
                                        className={`w-3 h-3 rounded-full transition-all duration-300 shadow-sm ${
                                            index === currentIndex 
                                            ? 'bg-brand-green-500 w-8' 
                                            : 'bg-white/50 hover:bg-white'
                                        }`}
                                        aria-label={`Go to slide ${index + 1}`}
                                    />
                                ))}
                            </div>
                        </div>
                    )}
                </AnimatedSection>
            </div>
        </div>
    );
};

