            name: formData.get('name') as string,
            email: formData.get('email') as string,
            subject: formData.get('subject') as string,
            message: formData.get('message') as string
        };

        try {
            await createInquiry(data);
            addToast(t('contactPage.form.success', 'Your message has been sent successfully!'), 'success');
            (e.target as HTMLFormElement).reset();
        } catch (error) {
            console.error('Inquiry submission failed:', error);
            addToast('Failed to send message. Please try again.', 'error');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="bg-brand-blue-800 p-8 rounded-md shadow-lg h-full border border-brand-blue-700">
            <h2 id="contact-form-heading" className="text-2xl font-bold text-white mb-6 font-roboto-condensed">{t('contactPage.form.title')}</h2>
            <form onSubmit={handleSubmit} className="space-y-6 font-lato">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label htmlFor="name" className="block text-brand-blue-50 mb-2">{t('contactPage.form.name')}</label>
                        <input type="text" id="name" name="name" className="w-full bg-brand-blue-900 border border-brand-blue-700 rounded-md py-2 px-3 text-white focus:outline-none focus:border-brand-green-500" required />
                    </div>
                    <div>
                        <label htmlFor="email" className="block text-brand-blue-50 mb-2">{t('contactPage.form.email')}</label>
                        <input type="email" id="email" name="email" className="w-full bg-brand-blue-900 border border-brand-blue-700 rounded-md py-2 px-3 text-white focus:outline-none focus:border-brand-green-500" required />
                    </div>
                </div>
                 <div>
                    <label htmlFor="department" className="block text-brand-blue-50 mb-2">{t('contactPage.form.department')}</label>
                    <select id="department" name="department" className="w-full bg-brand-blue-900 border border-brand-blue-700 rounded-md py-2 px-3 text-white focus:outline-none focus:border-brand-green-500">
                        {departments.map(dept => <option key={dept} value={dept}>{t(`contactPage.form.depts.${dept}`)}</option>)}
                    </select>
                </div>
                <div>
                    <label htmlFor="subject" className="block text-brand-blue-50 mb-2">{t('contactPage.form.subject')}</label>
                    <input type="text" id="subject" name="subject" className="w-full bg-brand-blue-900 border border-brand-blue-700 rounded-md py-2 px-3 text-white focus:outline-none focus:border-brand-green-500" required />
                </div>
                <div>
                    <label htmlFor="message" className="block text-brand-blue-50 mb-2">{t('contactPage.form.message')}</label>
                    <textarea id="message" name="message" rows={5} className="w-full bg-brand-blue-900 border border-brand-blue-700 rounded-md py-2 px-3 text-white focus:outline-none focus:border-brand-green-500" required></textarea>
                </div>
                <div>
                    <button type="submit" disabled={isSubmitting} className="w-full bg-brand-blue-500 hover:bg-brand-blue-600 text-white font-bold py-3 px-4 rounded-md transition-colors duration-300 font-roboto-condensed disabled:opacity-50 disabled:cursor-not-allowed">
                        {isSubmitting ? 'Submitting...' : t('contactPage.form.submit')}
                    </button>
                </div>
            </form>
        </div>
    );
};

