    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [activeSection, setActiveSection] = useState('overview');
    const [selectedProduct, setSelectedProduct] = useState<any>(null);
    const { t } = useLanguage();
    const { addToast } = useToast();

    // Refs for scroll spy
    const sectionRefs = useRef<{ [key: string]: HTMLDivElement | null }>({});

    useEffect(() => {
        if (id) {
            const fetchIndustry = async () => {
                try {
                    setLoading(true);
                    const data = await getIndustryById(id);
                    setIndustry(data);
                    window.scrollTo(0, 0);
                } catch (err) {
                    setError('Failed to load industry data.');
                } finally {
                    setLoading(false);
                }
            };
            fetchIndustry();
        }
    }, [id]);

    // Scroll Spy Logic
    useEffect(() => {
        const handleScroll = () => {
            const scrollPosition = window.scrollY + 150; // Offset for header

            const sections = ['overview', 'capabilities', 'products', 'innovation', 'contact'];

            for (const section of sections) {
                const element = document.getElementById(section);
                if (element) {
                    const { offsetTop, offsetHeight } = element;
                    if (scrollPosition >= offsetTop && scrollPosition < offsetTop + offsetHeight) {
                        setActiveSection(section);
                    }
                }
            }
        };

        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const scrollToSection = (sectionId: string) => {
        const element = document.getElementById(sectionId);
        if (element) {
            const offset = 80; // Height of sticky nav
            const elementPosition = element.getBoundingClientRect().top;
            const offsetPosition = elementPosition + window.pageYOffset - offset;

            window.scrollTo({
                top: offsetPosition,
                behavior: "smooth"
            });
        }
    };

    const handleInquirySubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        addToast('Secure inquiry transmitted to division HQ.', 'success');
        (e.target as HTMLFormElement).reset();
    };

    if (loading) return <div className="flex justify-center items-center h-screen bg-brand-blue-900"><Loader /></div>;
