                        <span className="font-semibold text-[#356267]">Click to upload</span> or drag files here.
                    </p>
                </div>
                <div className="mt-4 flex justify-end">
                    <Button variant="secondary" onClick={onClose}>Cancel</Button>
                </div>
            </div>
        </div>
    );
};

const MediaManager: React.FC = () => {
    const [assets, setAssets] = useState<MediaAsset[]>([]);
    const [loading, setLoading] = useState(true);
    const [viewMode, setViewMode] = useState<ViewMode>('grid');
    const [selectedAssets, setSelectedAssets] = useState<Set<string>>(new Set());
    const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
    const { addToast } = useToast();

    const fetchMedia = async () => {
        try {
            setLoading(true);
            const data = await getMedia();
            setAssets(data);
        } catch (error) {
            addToast('Failed to load media.', 'error');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchMedia();
    }, []);

    const handleSelectionChange = (assetId: string) => {
        setSelectedAssets(prev => {
            const newSelection = new Set(prev);
            if (newSelection.has(assetId)) {
                newSelection.delete(assetId);
            } else {
                newSelection.add(assetId);
            }
            return newSelection;
        });
    };

    const handleSelectAll = (event: React.ChangeEvent<HTMLInputElement>) => {
        if (event.target.checked) {
            setSelectedAssets(new Set(assets.map(a => a.id)));
        } else {
            setSelectedAssets(new Set());
        }
    };

    const handleFileUpload = async (files: FileList) => {
        if (!files || files.length === 0) return;
        const formData = new FormData();
        formData.append('file', files[0]);
        try {
            await uploadMedia(formData);
            addToast('File uploaded successfully', 'success');
            fetchMedia();
        } catch (error) {
            addToast('File upload failed.', 'error');
        }
    };

    const handleDeleteSelected = async () => {
        if (selectedAssets.size === 0) return;
        if (window.confirm(`Are you sure you want to delete ${selectedAssets.size} item(s)?`)) {
            try {
                await deleteMedia(Array.from(selectedAssets));
                addToast(`${selectedAssets.size} item(s) deleted.`, 'success');
                setSelectedAssets(new Set());
                fetchMedia();
            } catch (error) {
                addToast('Failed to delete items.', 'error');
            }
        }
    };

    const isAllSelected = selectedAssets.size === assets.length && assets.length > 0;
    const isIndeterminate = selectedAssets.size > 0 && selectedAssets.size < assets.length;

    return (
        <div className="space-y-6">
            {isUploadModalOpen && <UploadModal onClose={() => setIsUploadModalOpen(false)} onUpload={handleFileUpload} />}

            <Card>
                <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                     <div>
                        <h2 className="text-xl text-[#1E2B2B] font-montserrat font-bold">Media Manager</h2>
                        <p className="text-sm text-gray-500">Organize and manage your digital assets.</p>
                     </div>
                     <div className="flex items-center gap-4">
                        <Button variant="primary" onClick={() => setIsUploadModalOpen(true)}>
                            <span className="mr-2">+</span> Upload Media
                        </Button>
                     </div>
                </div>
            </Card>

            <Card>
                <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
                    <div className="flex items-center gap-2 w-full sm:w-auto">
                        <input type="text" placeholder="Search media..." className="w-full sm:w-auto bg-white border-gray-300 rounded-md py-1.5 px-3 text-[#1E2B2B] text-sm focus:outline-none focus:border-[#41737c] focus:ring-1 focus:ring-[#41737c]" />
                        <select className="bg-white border-gray-300 text-[#1E2B2B] text-sm rounded-md focus:ring-[#41737c] focus:border-[#41737c] py-1.5">
                            <option>All types</option>
                            <option>Image</option>
                            <option>Video</option>
                            <option>Document</option>
                        </select>
                    </div>

                    <div className="flex items-center gap-3 w-full sm:w-auto justify-between sm:justify-end">
                        <div className="flex items-center bg-gray-100 border border-gray-200 rounded-md p-0.5">
                            <button 
                                onClick={() => setViewMode('grid')} 
                                className={`p-1.5 rounded-md transition-all ${viewMode === 'grid' ? 'bg-white shadow-sm text-brand-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                                title="Grid View"
                            >
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z"></path></svg>
                            </button>
                            <button 
                                onClick={() => setViewMode('list')} 
                                className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-brand-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                                title="List View"
                            >
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16"></path></svg>
                            </button>
                        </div>

                        {selectedAssets.size > 0 && (
                             <Button variant="secondary" size="sm" className="!border-red-300 !text-red-600 hover:!bg-red-50" onClick={handleDeleteSelected}>
                                Delete ({selectedAssets.size})
                            </Button>
                        )}
                    </div>
                </div>

                {loading ? <div className="p-10 text-center text-gray-500">Loading media library...</div> : (
                    <>
                        {assets.length === 0 ? (
                            <div className="text-center py-10 text-gray-500">No media assets found. Upload some files to get started.</div>
                        ) : (
                            viewMode === 'grid' ? (
                                <GridView assets={assets} selectedAssets={selectedAssets} onSelectionChange={handleSelectionChange} />
                            ) : (
                                <ListView assets={assets} selectedAssets={selectedAssets} onSelectionChange={handleSelectionChange} onSelectAll={handleSelectAll} isAllSelected={isAllSelected} isIndeterminate={isIndeterminate} />
                            )
                        )}
                    </>
                )}
            </Card>
        </div>
    );
};

export default MediaManager;

