interface AdminDashboardProps {
    onNavigate: (section: AdminPanelSection) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onNavigate }) => {
    const [stats, setStats] = React.useState<any>(null);
    const [loading, setLoading] = React.useState(true);
    const { addToast } = useToast();

    const fetchStats = async () => {
        setLoading(true);
        try {
            const data = await getDashboardStats();
            setStats(data);
        } catch (err: any) {
            console.error(err);
            addToast('Failed to refresh data', 'error');
        } finally {
            setLoading(false);
        }
    };

    React.useEffect(() => {
        fetchStats();
    }, []);

    const handleDownloadReport = () => {
        addToast('Generating system report...', 'success');

        try {
            // Create content with fallbacks
            const reportContent = `
DEIG SYSTEM REPORT
Generated: ${new Date().toLocaleString()}
-----------------------------------
Total Visitors: ${stats?.visitors || 0}
Active Users: ${stats?.activeUsers || 0}
Open Vacancies: ${stats?.openVacancies || 0}
Unread Inquiries: ${stats?.unreadMessages || 0}
-----------------------------------
System Status: HEALTHY
            `;

            // Create blob and trigger download
            const blob = new Blob([reportContent], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `DEIG_Report_${new Date().toISOString().split('T')[0]}.txt`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        } catch (error) {
            console.error('Download failed:', error);
            addToast('Failed to download report', 'error');
        }
    };

    if (loading && !stats) return <div className="p-8 text-center text-gray-500">Loading Analytics...</div>;

