// --- MOCK DATABASE STATE (PERSISTENT) ---
const loadFromStorage = <T>(key: string, defaultValue: T): T => {
    try {
        const stored = localStorage.getItem(key);
        if (stored) return JSON.parse(stored);
    } catch (e) {
        console.error(`Failed to parse local ${key}`, e);
    }
    return defaultValue;
};

