export const getApplicantsByVacancy = async (vacancyId: string): Promise<Applicant[]> => {
    let apiApplicants: Applicant[] = [];
    try {
        // Try to fetch from API
        apiApplicants = await apiHelper(`/applicants/vacancy/${vacancyId}`);
        if (!Array.isArray(apiApplicants)) apiApplicants = [];
    } catch (e) {
        console.warn('API fetch failed for applicants, falling back to local');
    }

    // Always fetch local applicants to ensure we see ones created in offline/fallback mode
    const localApplicants = LOCAL_APPLICANTS.filter(app => app.vacancyId === vacancyId);

    // Merge API and Local applicants, prioritizing local ones if needed or simply concatenating
    // Use a Map to dedup by ID if there's any chance of overlap
    const combined = [...apiApplicants, ...localApplicants];
    const uniqueApplicants = Array.from(new Map(combined.map(item => [item.id, item])).values());

    return uniqueApplicants;
};

export const createApplicant = async (formData: FormData): Promise<Applicant> => {
    try {
        // Attempt API call
        return await apiHelper('/applicants', { method: 'POST', body: formData });
    } catch (e) {
        // Fallback Logic: Store locally if API fails
        console.log("Saving applicant locally due to API error");

        const cvFile = formData.get('cv') as File | null;
        let mockCvUrl = '#';

        if (cvFile) {
            try { 
                // Store actual file content as Base64 for immediate preview
                mockCvUrl = await fileToBase64(cvFile); 
            } catch (err) { 
                console.error("Failed to convert file", err); 
            }
        }

        const newApplicant: Applicant = {
            id: `app-local-${Date.now()}`,
            name: (formData.get('name') as string) || 'Applicant Name',
            email: (formData.get('email') as string) || 'applicant@example.com',
            appliedDate: new Date().toISOString(),
            vacancyId: (formData.get('vacancyId') as string) || 'unknown',
            status: 'New',
            cvUrl: mockCvUrl,
            rating: 0
        };

        LOCAL_APPLICANTS.push(newApplicant);
        saveToStorage('deig_applicants', LOCAL_APPLICANTS);

        // Return promise to simulate network delay so UI updates smoothly
        return new Promise((resolve) => setTimeout(() => resolve(newApplicant), 500));
    }
};

