        const index = LOCAL_APPLICANTS.findIndex(a => a.id === id);
        if (index !== -1) {
            LOCAL_APPLICANTS[index] = { ...LOCAL_APPLICANTS[index], status };
            saveToStorage('deig_applicants', LOCAL_APPLICANTS);
            return Promise.resolve(LOCAL_APPLICANTS[index]);
        }
        throw new Error("Applicant not found");
    }
};

