    // This is critical because the 'LOCAL_APPLICANTS' variable might be stale if not reloaded
    const currentLocalApplicants = loadFromStorage<Applicant[]>('deig_applicants', LOCAL_APPLICANTS);
    const specificLocalApplicants = currentLocalApplicants.filter(app => app.vacancyId === vacancyId);

    // Merge API and Local applicants, favoring local ones if duplicates exist (by ID)
    const combined = [...apiApplicants];

    specificLocalApplicants.forEach(localApp => {
        if (!combined.find(a => a.id === localApp.id)) {
            combined.push(localApp);
        }
    });

    return combined;
};

export const createApplicant = async (formData: FormData): Promise<Applicant> => {
    try {
        // Attempt API call
        return await apiHelper('/applicants', { method: 'POST', body: formData });
    } catch (e) {
        // Fallback Logic: Store locally if API fails
        console.log("Saving applicant locally due to API error");

        const cvFile = formData.get('cv') as File | null;
        let mockCvUrl = '#';

        if (cvFile) {
            try { 
                // Store actual file content as Base64 for immediate preview
                mockCvUrl = await fileToBase64(cvFile); 
            } catch (err) { 
                console.error("Failed to convert file", err); 
            }
        }

        const newApplicant: Applicant = {
            id: `app-local-${Date.now()}`,
            name: (formData.get('name') as string) || 'Applicant Name',
            email: (formData.get('email') as string) || 'applicant@example.com',
            appliedDate: new Date().toISOString(),
            vacancyId: (formData.get('vacancyId') as string) || 'unknown',
            status: 'New',
            cvUrl: mockCvUrl,
            rating: 0
        };

        // RELOAD -> APPEND -> SAVE
        // This ensures no race conditions with the module-level variable
        const currentApplicants = loadFromStorage<Applicant[]>('deig_applicants', LOCAL_APPLICANTS);
        currentApplicants.push(newApplicant);
        saveToStorage('deig_applicants', currentApplicants);

        // Update the in-memory reference too
        LOCAL_APPLICANTS = currentApplicants;

        // Return promise to simulate network delay so UI updates smoothly
        return new Promise((resolve) => setTimeout(() => resolve(newApplicant), 600));
    }
};

export const updateApplicantStatus = async (id: string, status: ApplicantStatus): Promise<Applicant> => {
    try {
        return await apiHelper(`/applicants/${id}/status`, { method: 'PUT', body: JSON.stringify({ status }) });
    } catch (e) {
        // Reload fresh to find the right one
        const currentApplicants = loadFromStorage<Applicant[]>('deig_applicants', LOCAL_APPLICANTS);
        const index = currentApplicants.findIndex(a => a.id === id);

        if (index !== -1) {
            currentApplicants[index] = { ...currentApplicants[index], status };
            saveToStorage('deig_applicants', currentApplicants);
            LOCAL_APPLICANTS = currentApplicants;
            return Promise.resolve(currentApplicants[index]);
        }
        throw new Error("Applicant not found locally");
    }
};

